  public var RELATIVE_PERMEABILITY_IMAGINARY: Double { let o = _accessor.offset(VT.RELATIVE_PERMEABILITY_IMAGINARY); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
